/*
 * cm4sim - instruction-level model of an ARMv7E-M core (Cortex-M4 class)
 * for testing the scmRTOS Cortex-M port.
 *
 * Model:
 *   - Thumb/Thumb-2 integer instruction set (the subset generated by clang/gcc
 *     for the kernel and the test), FPv4-SP subset: VLDR/VSTR, VLDM/VSTM,
 *     VMOV (core <-> S), VADD/VSUB/VMUL.F32, VMRS/VMSR.
 *   - Exception model: NVIC with 4 implemented priority bits (as STM32F4),
 *     priority grouping (AIRCR.PRIGROUP), PRIMASK, BASEPRI/BASEPRI_MAX,
 *     PendSV, SysTick, nested preemption, stack alignment (xPSR bit 9),
 *     MSP/PSP, CONTROL.SPSEL/FPCA, basic and extended (FP) frames.
 *     FP frames are stacked eagerly (lazy stacking is not modelled).
 *   - One instruction per cycle; exceptions are taken between instructions.
 *     MSR to PRIMASK/BASEPRI takes effect for the next instruction.
 *   - Test device at 0x40000000: console, exit, cycle counter, random
 *     asynchronous interrupt generator.
 *
 * Usage: cm4sim [-s seed] [-r rate_per_million] [-m max_cycles] [-t] image.elf
 */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

//------------------------------------------------------------------------------
//  Memory map
#define FLASH_BASE  0x00000000u
#define FLASH_SIZE  (512u * 1024)
#define RAM_BASE    0x20000000u
#define RAM_SIZE    (256u * 1024)
#define DEV_BASE    0x40000000u
#define DEV_SIZE    0x1000u

static uint8_t flash[FLASH_SIZE];
static uint8_t ram[RAM_SIZE];

//------------------------------------------------------------------------------
//  Core state
static uint32_t R[16];                  // R13 unused: see msp/psp
static uint32_t msp, psp;
static bool N, Z, C, V, Q;
static uint32_t ipsr;
static uint8_t  itstate;
static uint32_t primask, basepri, control;
static uint32_t S[32], fpscr;
static uint32_t pc, next_pc;
static uint64_t cyc;
static bool     exc_returned;      // set by exception return: IT state was restored
static bool     trace;
static bool     strict_ret;        // -x: odd exception return address is an error

#define NEXC        (16 + 64)
#define EXC_NMI     2
#define EXC_HARD    3
#define EXC_SVC     11
#define EXC_PENDSV  14
#define EXC_SYSTICK 15

static bool    active[NEXC], pending[NEXC], enabled[NEXC];
static uint8_t prio[NEXC];
static uint32_t aircr_prigroup, vtor, fpccr = 0xC0000000u, cpacr;
static uint32_t st_ctrl, st_load, st_val;

// test device
static uint32_t dev_rand_mask;          // IRQs triggered at random
static uint32_t dev_rate = 0;           // per million cycles
static uint64_t pend_cycle[NEXC];       // cycle at which exception became pending
static uint64_t rng_state = 1;
static uint64_t max_cycles = 400000000ull;
static uint32_t dev_scratch[64];

static void die(const char *msg)
{
    fprintf(stderr, "cm4sim: %s at pc=%08x cycle=%llu ipsr=%u\n", msg, pc,
            (unsigned long long)cyc, ipsr);
    exit(3);
}

static uint32_t rnd32(void)
{
    rng_state ^= rng_state << 13; rng_state ^= rng_state >> 7; rng_state ^= rng_state << 17;
    return (uint32_t)(rng_state >> 16);
}

static bool handler_mode(void) { return ipsr != 0; }
static uint32_t *cur_sp(void) { return (handler_mode() || !(control & 2)) ? &msp : &psp; }

//------------------------------------------------------------------------------
//  Memory and devices
static void set_pending(int e)
{
    if(!pending[e])
        pend_cycle[e] = cyc;
    pending[e] = true;
}

static uint32_t icsr_read(void)
{
    uint32_t v = ipsr & 0x1FF;
    if(pending[EXC_PENDSV]) v |= 1u << 28;
    if(pending[EXC_SYSTICK]) v |= 1u << 26;
    return v;
}

static uint32_t scs_read(uint32_t a, int size)
{
    // byte-addressable priority registers
    if(a >= 0xE000E400u && a < 0xE000E400u + (NEXC - 16))
    {
        uint32_t v = 0;
        for(int i = 0; i < size; i++)
            if(a + i - 0xE000E400u < NEXC - 16) v |= (uint32_t)prio[16 + a + i - 0xE000E400u] << (8 * i);
        return v;
    }
    if(a >= 0xE000ED18u && a < 0xE000ED24u)
    {
        uint32_t v = 0;
        for(int i = 0; i < size; i++) v |= (uint32_t)prio[4 + a + i - 0xE000ED18u] << (8 * i);
        return v;
    }
    switch(a)
    {
    case 0xE000E010: { uint32_t v = st_ctrl; st_ctrl &= ~0x10000u; return v; }
    case 0xE000E014: return st_load;
    case 0xE000E018: return st_val;
    case 0xE000E01C: return 0;
    case 0xE000ED00: return 0x410FC241;
    case 0xE000ED04: return icsr_read();
    case 0xE000ED08: return vtor;
    case 0xE000ED0C: return 0xFA050000u | (aircr_prigroup << 8);
    case 0xE000ED24: {
        uint32_t v = 0;
        if(active[EXC_SVC]) v |= 1u << 7;
        if(active[EXC_PENDSV]) v |= 1u << 10;
        if(active[EXC_SYSTICK]) v |= 1u << 11;
        return v;
    }
    case 0xE000ED88: return cpacr;
    case 0xE000EF34: return fpccr;
    }
    if(a >= 0xE000E100u && a < 0xE000E180u) { int b = (a - 0xE000E100u) * 8; uint32_t v = 0; for(int i = 0; i < 32; i++) if(16 + b + i < NEXC && enabled[16 + b + i]) v |= 1u << i; return v; }
    if(a >= 0xE000E180u && a < 0xE000E200u) { int b = (a - 0xE000E180u) * 8; uint32_t v = 0; for(int i = 0; i < 32; i++) if(16 + b + i < NEXC && enabled[16 + b + i]) v |= 1u << i; return v; }
    if(a >= 0xE000E200u && a < 0xE000E300u) { int b = ((a - 0xE000E200u) & 0x7F) * 8; uint32_t v = 0; for(int i = 0; i < 32; i++) if(16 + b + i < NEXC && pending[16 + b + i]) v |= 1u << i; return v; }
    if(a >= 0xE000E300u && a < 0xE000E380u) { int b = (a - 0xE000E300u) * 8; uint32_t v = 0; for(int i = 0; i < 32; i++) if(16 + b + i < NEXC && active[16 + b + i]) v |= 1u << i; return v; }
    return 0;
}

static void scs_write(uint32_t a, uint32_t v, int size)
{
    if(a >= 0xE000E400u && a < 0xE000E400u + (NEXC - 16))
    {
        for(int i = 0; i < size; i++)
            if(a + i - 0xE000E400u < NEXC - 16) prio[16 + a + i - 0xE000E400u] = (v >> (8 * i)) & 0xF0;
        return;
    }
    if(a >= 0xE000ED18u && a < 0xE000ED24u)
    {
        for(int i = 0; i < size; i++)
        {
            int e = 4 + a + i - 0xE000ED18u;
            if(e == 11 || e >= 14 || (e >= 4 && e <= 6)) prio[e] = (v >> (8 * i)) & 0xF0;
        }
        return;
    }
    if(size != 4) die("non-word SCS write");
    switch(a)
    {
    case 0xE000E010: st_ctrl = (st_ctrl & 0x10000u) | (v & 7); return;
    case 0xE000E014: st_load = v & 0xFFFFFF; return;
    case 0xE000E018: st_val = 0; st_ctrl &= ~0x10000u; return;
    case 0xE000ED04:
        if(v & (1u << 28)) set_pending(EXC_PENDSV);
        if(v & (1u << 27)) pending[EXC_PENDSV] = false;
        if(v & (1u << 26)) set_pending(EXC_SYSTICK);
        if(v & (1u << 25)) pending[EXC_SYSTICK] = false;
        if(v & (1u << 31)) set_pending(EXC_NMI);
        return;
    case 0xE000ED08: vtor = v & ~0x7Fu; return;
    case 0xE000ED0C: if((v >> 16) == 0x05FA) aircr_prigroup = (v >> 8) & 7; return;
    case 0xE000ED88: cpacr = v; return;
    case 0xE000EF34: fpccr = v; return;
    case 0xE000EF00: set_pending(16 + (v & 0x1FF)); return;   // STIR
    }
    if(a >= 0xE000E100u && a < 0xE000E180u) { int b = (a - 0xE000E100u) * 8; for(int i = 0; i < 32; i++) if((v >> i & 1) && 16 + b + i < NEXC) enabled[16 + b + i] = true; return; }
    if(a >= 0xE000E180u && a < 0xE000E200u) { int b = (a - 0xE000E180u) * 8; for(int i = 0; i < 32; i++) if((v >> i & 1) && 16 + b + i < NEXC) enabled[16 + b + i] = false; return; }
    if(a >= 0xE000E200u && a < 0xE000E280u) { int b = (a - 0xE000E200u) * 8; for(int i = 0; i < 32; i++) if((v >> i & 1) && 16 + b + i < NEXC) set_pending(16 + b + i); return; }
    if(a >= 0xE000E280u && a < 0xE000E300u) { int b = (a - 0xE000E280u) * 8; for(int i = 0; i < 32; i++) if((v >> i & 1) && 16 + b + i < NEXC) pending[16 + b + i] = false; return; }
}

//  Test device registers (word access)
//  +0x00 W  console character
//  +0x04 W  exit with code
//  +0x08 R  cycle counter (low)    +0x0C R cycle counter (high)
//  +0x10 RW random IRQ mask (bit n -> IRQ n)
//  +0x14 RW random IRQ rate per million cycles
//  +0x18 R  random number
//  +0x100 + 4*n R  cycle (low) at which exception n became pending
//  +0x400 .. RW scratch
static uint32_t dev_read(uint32_t off)
{
    switch(off)
    {
    case 0x08: return (uint32_t)cyc;
    case 0x0C: return (uint32_t)(cyc >> 32);
    case 0x10: return dev_rand_mask;
    case 0x14: return dev_rate;
    case 0x18: return rnd32();
    }
    if(off >= 0x100 && off < 0x100 + 4 * NEXC) return (uint32_t)pend_cycle[(off - 0x100) / 4];
    if(off >= 0x400 && off < 0x400 + sizeof dev_scratch) return dev_scratch[(off - 0x400) / 4];
    return 0;
}

static void dev_write(uint32_t off, uint32_t v)
{
    switch(off)
    {
    case 0x00: putchar((int)(v & 0xFF)); fflush(stdout); return;
    case 0x04: fflush(stdout); fprintf(stderr, "cm4sim: exit %u after %llu cycles\n", v, (unsigned long long)cyc); exit((int)v);
    case 0x10: dev_rand_mask = v; return;
    case 0x14: dev_rate = v; return;
    }
    if(off >= 0x400 && off < 0x400 + sizeof dev_scratch) { dev_scratch[(off - 0x400) / 4] = v; return; }
}

static uint8_t *mem_ptr(uint32_t a, int size)
{
    if(a - FLASH_BASE <= FLASH_SIZE - size) return &flash[a - FLASH_BASE];
    if(a - RAM_BASE <= RAM_SIZE - size) return &ram[a - RAM_BASE];
    return NULL;
}

static uint32_t rd(uint32_t a, int size)
{
    uint8_t *p = mem_ptr(a, size);
    if(p) { uint32_t v = 0; memcpy(&v, p, size); return v; }
    if(a >= 0xE000E000u && a < 0xE000F000u) return scs_read(a, size);
    if(a >= DEV_BASE && a < DEV_BASE + DEV_SIZE) return dev_read(a - DEV_BASE);
    fprintf(stderr, "read %08x\n", a); die("bus fault (read)");
    return 0;
}

static void wr(uint32_t a, uint32_t v, int size)
{
    if(a - RAM_BASE <= RAM_SIZE - size) { memcpy(&ram[a - RAM_BASE], &v, size); return; }
    if(a >= 0xE000E000u && a < 0xE000F000u) { scs_write(a, v, size); return; }
    if(a >= DEV_BASE && a < DEV_BASE + DEV_SIZE) { dev_write(a - DEV_BASE, v); return; }
    fprintf(stderr, "write %08x = %08x\n", a, v); die("bus fault (write)");
}

static uint32_t rd32(uint32_t a) { return rd(a, 4); }
static void wr32(uint32_t a, uint32_t v) { wr(a, v, 4); }

//------------------------------------------------------------------------------
//  Registers
static uint32_t rreg(int n)
{
    if(n == 15) return pc + 4;
    if(n == 13) return *cur_sp();
    return R[n];
}

static void exc_return(uint32_t excret);

static void branch_to(uint32_t addr)
{
    if(handler_mode() && (addr & 0xF0000000u) == 0xF0000000u) { exc_return(addr); return; }
    if(!(addr & 1)) die("branch to ARM state");
    next_pc = addr & ~1u;
}

static void wreg(int n, uint32_t v)
{
    if(n == 15) { next_pc = v & ~1u; return; }       // ALU write: no interworking
    if(n == 13) { *cur_sp() = v & ~3u; return; }
    R[n] = v;
}

static void load_pc(uint32_t v) { branch_to(v); }   // LDR/LDM/POP: interworking

static uint32_t xpsr_read(void)
{
    uint32_t v = (N << 31) | (Z << 30) | (C << 29) | (V << 28) | (Q << 27) | (1u << 24);
    v |= (uint32_t)(itstate & 3) << 25 | (uint32_t)(itstate >> 2) << 10;
    return v | ipsr;
}

//------------------------------------------------------------------------------
//  Exceptions
static uint32_t group_mask(void) { return (0xFFu << (aircr_prigroup + 1)) & 0xFF; }

static int exc_gprio(int e)
{
    if(e == 1) return -3;
    if(e == EXC_NMI) return -2;
    if(e == EXC_HARD) return -1;
    return prio[e] & group_mask();
}

static int exec_priority(void)
{
    int p = 256;
    for(int e = 2; e < NEXC; e++)
        if(active[e]) { int g = exc_gprio(e); if(g < p) p = g; }
    if(basepri) { int b = basepri & group_mask(); if(b < p) p = b; }
    if(primask && p > 0) p = 0;
    return p;
}

static bool fpu_present;

static void exc_entry(int e)
{
    bool fp = fpu_present && (control & 4);
    uint32_t framesize = fp ? 0x68 : 0x20;
    uint32_t *spp = cur_sp();
    uint32_t sp = *spp;
    uint32_t align = (sp >> 2) & 1;
    uint32_t frame = (sp - framesize) & ~4u;
    uint32_t xpsr = xpsr_read() | (align << 9);

    wr32(frame + 0x00, R[0]);  wr32(frame + 0x04, R[1]);
    wr32(frame + 0x08, R[2]);  wr32(frame + 0x0C, R[3]);
    wr32(frame + 0x10, R[12]); wr32(frame + 0x14, R[14]);
    wr32(frame + 0x18, pc);    wr32(frame + 0x1C, xpsr);
    if(fp)
    {
        for(int i = 0; i < 16; i++) wr32(frame + 0x20 + 4 * i, S[i]);
        wr32(frame + 0x60, fpscr);
    }
    *spp = frame;

    uint32_t lr;
    if(handler_mode())      lr = 0xFFFFFFF1u;
    else if(control & 2)    lr = 0xFFFFFFFDu;
    else                    lr = 0xFFFFFFF9u;
    if(fp) lr &= ~0x10u;
    R[14] = lr;

    ipsr = e; itstate = 0;
    active[e] = true; pending[e] = false;
    control &= ~4u;
    pc = rd32(vtor + 4 * e) & ~1u;
    if(trace) fprintf(stderr, "  >> exception %d, sp=%08x\n", e, frame);
}

static void exc_return(uint32_t excret)
{
    int e = ipsr;
    if(!active[e]) die("return from inactive exception");
    active[e] = false;

    bool to_thread;
    switch(excret & 0xF)
    {
    case 0x1: to_thread = false; break;
    case 0x9: to_thread = true; control &= ~2u; break;
    case 0xD: to_thread = true; control |= 2u; break;
    default: die("bad EXC_RETURN"); return;
    }
    if(to_thread)
        for(int i = 2; i < NEXC; i++) if(active[i]) die("return to thread with active exceptions");

    uint32_t *spp = to_thread ? ((control & 2) ? &psp : &msp) : &msp;
    uint32_t frame = *spp;
    bool fp = !(excret & 0x10);
    if(fp && !fpu_present) die("FP frame without FPU");

    R[0] = rd32(frame + 0x00); R[1] = rd32(frame + 0x04);
    R[2] = rd32(frame + 0x08); R[3] = rd32(frame + 0x0C);
    R[12] = rd32(frame + 0x10); R[14] = rd32(frame + 0x14);
    uint32_t ret = rd32(frame + 0x18);
    uint32_t xpsr = rd32(frame + 0x1C);
    if(fp)
    {
        for(int i = 0; i < 16; i++) S[i] = rd32(frame + 0x20 + 4 * i);
        fpscr = rd32(frame + 0x60);
    }
    uint32_t framesize = fp ? 0x68 : 0x20;
    *spp = frame + framesize + (((xpsr >> 9) & 1) ? 4 : 0);

    N = xpsr >> 31 & 1; Z = xpsr >> 30 & 1; C = xpsr >> 29 & 1; V = xpsr >> 28 & 1; Q = xpsr >> 27 & 1;
    itstate = ((xpsr >> 25) & 3) | (((xpsr >> 10) & 0x3F) << 2);
    ipsr = xpsr & 0x1FF;
    if(to_thread && ipsr != 0) die("stacked IPSR != 0 on return to thread");
    if(!to_thread && (ipsr == 0 || !active[ipsr])) die("stacked IPSR does not match an active exception");
    if(fp) control |= 4u; else control &= ~4u;
    if(ret & 1)
    {
        // UNPREDICTABLE in ARMv7-M; Cortex-M3/M4 ignore bit 0. Report once.
        static bool warned;
        if(!warned) { fprintf(stderr, "cm4sim: warning: exception return address %08x has bit 0 set\n", ret); warned = true; }
        if(strict_ret) die("return address with bit 0 set");
        ret &= ~1u;
    }
    next_pc = ret;
    exc_returned = true;
    if(trace) fprintf(stderr, "  << return from %d to %08x\n", e, ret);
}

static void check_exceptions(void)
{
    int best = -1, bp = 0, bfull = 0;
    for(int e = 2; e < NEXC; e++)
    {
        if(!pending[e]) continue;
        if(e >= 16 && !enabled[e]) continue;
        int g = exc_gprio(e), f = e < 4 ? g : prio[e];
        if(best < 0 || g < bp || (g == bp && f < bfull)) { best = e; bp = g; bfull = f; }
    }
    if(best >= 0 && bp < exec_priority())
        exc_entry(best);
}

//------------------------------------------------------------------------------
//  ALU helpers
static uint32_t add_c(uint32_t a, uint32_t b, bool cin, bool *co, bool *ov)
{
    uint64_t u = (uint64_t)a + b + cin;
    int64_t  s = (int64_t)(int32_t)a + (int32_t)b + cin;
    uint32_t r = (uint32_t)u;
    *co = (u >> 32) & 1;
    *ov = (int64_t)(int32_t)r != s;
    return r;
}

static void setnz(uint32_t r) { N = r >> 31; Z = r == 0; }

static uint32_t shift_c(uint32_t v, int type, int n, bool cin, bool *cout)
{
    *cout = cin;
    if(n == 0) return v;
    switch(type)
    {
    case 0: // LSL
        if(n >= 33) { *cout = 0; return 0; }
        *cout = (n <= 32) ? ((uint64_t)v >> (32 - n)) & 1 : 0;
        return n >= 32 ? 0 : v << n;
    case 1: // LSR
        if(n > 32) { *cout = 0; return 0; }
        *cout = (v >> (n - 1)) & 1;
        return n == 32 ? 0 : v >> n;
    case 2: // ASR
        if(n >= 32) { *cout = v >> 31; return (int32_t)v >> 31; }
        *cout = (v >> (n - 1)) & 1;
        return (uint32_t)((int32_t)v >> n);
    case 3: // ROR
        n &= 31;
        { uint32_t r = n ? (v >> n) | (v << (32 - n)) : v; *cout = r >> 31; return r; }
    case 4: // RRX
        *cout = v & 1;
        return (v >> 1) | ((uint32_t)cin << 31);
    }
    return v;
}

// shift by immediate (DecodeImmShift)
static uint32_t shift_imm(uint32_t v, int type, int imm5, bool *cout)
{
    if(type == 0) return shift_c(v, 0, imm5, C, cout);
    if(type == 1 || type == 2) return shift_c(v, type, imm5 ? imm5 : 32, C, cout);
    if(imm5 == 0) return shift_c(v, 4, 1, C, cout);
    return shift_c(v, 3, imm5, C, cout);
}

static uint32_t expand_imm_c(uint32_t imm12, bool *cout)
{
    *cout = C;
    if((imm12 >> 10) == 0)
    {
        uint32_t b = imm12 & 0xFF;
        switch((imm12 >> 8) & 3)
        {
        case 0: return b;
        case 1: return b << 16 | b;
        case 2: return b << 24 | b << 8;
        default: return b << 24 | b << 16 | b << 8 | b;
        }
    }
    uint32_t un = 0x80 | (imm12 & 0x7F);
    int rot = imm12 >> 7;
    uint32_t r = (un >> rot) | (un << (32 - rot));
    *cout = r >> 31;
    return r;
}

static bool cond_pass(int c)
{
    bool r;
    switch(c >> 1)
    {
    case 0: r = Z; break;
    case 1: r = C; break;
    case 2: r = N; break;
    case 3: r = V; break;
    case 4: r = C && !Z; break;
    case 5: r = N == V; break;
    case 6: r = !Z && N == V; break;
    default: return true;
    }
    return (c & 1) ? !r : r;
}

static bool in_it(void) { return (itstate & 0xF) != 0; }

// Data processing operation with op as in 32-bit encodings.
// Returns false for unknown op.
static bool dp_op(int op, int rd, uint32_t a, uint32_t b, bool shc, bool s)
{
    uint32_t r; bool co = shc, ov = V, wb = true;
    switch(op)
    {
    case 0x0: r = a & b; if(rd == 15) { if(!s) return false; wb = false; } break;          // AND/TST
    case 0x1: r = a & ~b; break;                                                            // BIC
    case 0x2: r = a | b; break;                                                             // ORR/MOV
    case 0x3: r = a | ~b; break;                                                            // ORN/MVN
    case 0x4: r = a ^ b; if(rd == 15) { if(!s) return false; wb = false; } break;          // EOR/TEQ
    case 0x8: r = add_c(a, b, 0, &co, &ov); if(rd == 15) { if(!s) return false; wb = false; } break; // ADD/CMN
    case 0xA: r = add_c(a, b, C, &co, &ov); break;                                          // ADC
    case 0xB: r = add_c(a, ~b, C, &co, &ov); break;                                         // SBC
    case 0xD: r = add_c(a, ~b, 1, &co, &ov); if(rd == 15) { if(!s) return false; wb = false; } break; // SUB/CMP
    case 0xE: r = add_c(b, ~a, 1, &co, &ov); break;                                         // RSB
    default: return false;
    }
    if(wb) wreg(rd, r);
    if(s) { setnz(r); C = co; V = ov; }
    return true;
}

//------------------------------------------------------------------------------
//  System registers
static uint32_t mrs(int sysm)
{
    switch(sysm)
    {
    case 0: case 1: case 2: case 3: case 5: case 6: case 7:
    {
        uint32_t v = 0;
        if(!(sysm & 4)) v |= xpsr_read() & 0xF8000000u;
        if(sysm & 1) v |= ipsr;
        return v;
    }
    case 8: return msp;
    case 9: return psp;
    case 16: return primask;
    case 17: case 18: return basepri;
    case 19: return 0;
    case 20: return control;
    }
    die("MRS: unknown SYSm");
    return 0;
}

static void msr(int sysm, uint32_t v)
{
    switch(sysm)
    {
    case 0: case 1: case 2: case 3:
        N = v >> 31 & 1; Z = v >> 30 & 1; C = v >> 29 & 1; V = v >> 28 & 1; Q = v >> 27 & 1;
        return;
    case 5: case 6: case 7: return;
    case 8: msp = v & ~3u; return;
    case 9: psp = v & ~3u; return;
    case 16: primask = v & 1; return;
    case 17: basepri = v & 0xF0; return;
    case 18: v &= 0xF0; if(v && (basepri == 0 || v < basepri)) basepri = v; return;
    case 19: return;
    case 20:
        if(!handler_mode()) control = (control & ~2u) | (v & 2);
        if(fpu_present) control = (control & ~4u) | (v & 4);
        return;
    }
    die("MSR: unknown SYSm");
}

//------------------------------------------------------------------------------
//  Load/store helpers
static uint32_t ld(uint32_t a, int size, bool sgn)
{
    uint32_t v = rd(a, size);
    if(sgn && size == 1) v = (uint32_t)(int8_t)v;
    if(sgn && size == 2) v = (uint32_t)(int16_t)v;
    return v;
}

static void ldm(int rn, uint32_t list, bool wback, bool db)
{
    int cnt = __builtin_popcount(list);
    uint32_t base = rreg(rn);
    uint32_t a = db ? base - 4 * cnt : base;
    if(a & 3) die("unaligned LDM");
    uint32_t newbase = db ? base - 4 * cnt : base + 4 * cnt;
    uint32_t pcv = 0; bool load_pc_flag = false;
    for(int i = 0; i < 16; i++)
        if(list >> i & 1)
        {
            uint32_t v = rd32(a); a += 4;
            if(i == 15) { pcv = v; load_pc_flag = true; }
            else if(i == 13) wreg(13, v);
            else R[i] = v;
        }
    if(wback && !(list >> rn & 1)) wreg(rn, newbase);
    if(load_pc_flag) load_pc(pcv);
}

static void stm(int rn, uint32_t list, bool wback, bool db)
{
    int cnt = __builtin_popcount(list);
    uint32_t base = rreg(rn);
    uint32_t a = db ? base - 4 * cnt : base;
    if(a & 3) die("unaligned STM");
    for(int i = 0; i < 16; i++)
        if(list >> i & 1) { wr32(a, rreg(i)); a += 4; }
    if(wback) wreg(rn, db ? base - 4 * cnt : base + 4 * cnt);
}

//------------------------------------------------------------------------------
//  FP helpers (single precision, plain C float semantics)
static float sf(int i) { float f; memcpy(&f, &S[i], 4); return f; }
static void ssf(int i, float f) { memcpy(&S[i], &f, 4); }

static void fp_used(void)
{
    if(!fpu_present || ((cpacr >> 20) & 0xF) != 0xF) die("FP instruction with FPU disabled");
    control |= 4u;     // FPCA
}

static bool exec_coproc(uint32_t hw1, uint32_t hw2)
{
    int coproc = (hw2 >> 8) & 0xF;
    if(coproc != 10 && coproc != 11) return false;
    if(coproc == 11) return false;           // double precision not supported
    fp_used();

    int D = (hw1 >> 6) & 1, Vd = (hw2 >> 12) & 0xF, sd = (Vd << 1) | D;
    int rn = hw1 & 0xF;

    // Extension register load/store: 1110 110x xxxx
    if((hw1 & 0xFE00) == 0xEC00 && (hw1 & 0x01A0) != 0)
    {
        int P = hw1 >> 8 & 1, U = hw1 >> 7 & 1, W = hw1 >> 5 & 1, L = hw1 >> 4 & 1;
        uint32_t imm = (hw2 & 0xFF) * 4;
        if(P && !W)     // VLDR/VSTR
        {
            uint32_t base = rn == 15 ? (rreg(15) & ~3u) : rreg(rn);
            uint32_t a = U ? base + imm : base - imm;
            if(L) S[sd] = rd32(a); else wr32(a, S[sd]);
            return true;
        }
        // VLDM/VSTM
        int n = hw2 & 0xFF;
        uint32_t base = rreg(rn);
        uint32_t a = U ? base : base - imm;
        for(int i = 0; i < n; i++)
        {
            if(L) S[sd + i] = rd32(a + 4 * i); else wr32(a + 4 * i, S[sd + i]);
        }
        if(W) wreg(rn, U ? base + imm : base - imm);
        return true;
    }
    // VMOV core <-> single: 1110 1110 000 op Vn | Rt 1010 N001 0000
    if((hw1 & 0xFFE0) == 0xEE00 && (hw2 & 0x0F7F) == 0x0A10)
    {
        int sn = ((hw1 & 0xF) << 1) | ((hw2 >> 7) & 1), rt = hw2 >> 12;
        if(hw1 & 0x10) wreg(rt, S[sn]); else S[sn] = rreg(rt);
        return true;
    }
    // VMRS/VMSR FPSCR
    if(hw1 == 0xEEF1 && (hw2 & 0x0FFF) == 0x0A10) { int rt = hw2 >> 12; if(rt == 15) { N = fpscr >> 31; Z = fpscr >> 30 & 1; C = fpscr >> 29 & 1; V = fpscr >> 28 & 1; } else wreg(rt, fpscr); return true; }
    if(hw1 == 0xEEE1 && (hw2 & 0x0FFF) == 0x0A10) { fpscr = rreg(hw2 >> 12); return true; }
    // Data processing: 1110 1110 xxxx | .... 1010 ...0 ....
    if((hw1 & 0xFF00) == 0xEE00 && (hw2 & 0x0E10) == 0x0A00)
    {
        int sn = ((hw1 & 0xF) << 1) | ((hw2 >> 7) & 1);
        int sm = ((hw2 & 0xF) << 1) | ((hw2 >> 5) & 1);
        int opc1 = (hw1 >> 4) & 0xB, opc3 = (hw2 >> 6) & 1;
        if(opc1 == 0x3 && !opc3) { ssf(sd, sf(sn) + sf(sm)); return true; }
        if(opc1 == 0x3 && opc3)  { ssf(sd, sf(sn) - sf(sm)); return true; }
        if(opc1 == 0x2 && !opc3) { ssf(sd, sf(sn) * sf(sm)); return true; }
        if(opc1 == 0x8 && !opc3) { ssf(sd, sf(sn) / sf(sm)); return true; }
        if(opc1 == 0xB && !opc3)                                                          // VMOV imm
        {
            uint32_t imm8 = ((hw1 & 0xF) << 4) | (hw2 & 0xF), b6 = (imm8 >> 6) & 1;
            S[sd] = ((imm8 >> 7) << 31) | ((b6 ^ 1) << 30) | ((b6 ? 0x1Fu : 0) << 25) | (((imm8 >> 4) & 3) << 23) | ((imm8 & 0xF) << 19);
            return true;
        }
        if(opc1 == 0xB && opc3)
        {
            int opc2 = hw1 & 0xF;
            if(opc2 == 0 && !(hw2 & 0x80)) { S[sd] = S[sm]; return true; }                // VMOV reg
            if(opc2 == 0 &&  (hw2 & 0x80)) { S[sd] = S[sm] & 0x7FFFFFFFu; return true; }  // VABS
            if(opc2 == 1 && !(hw2 & 0x80)) { S[sd] = S[sm] ^ 0x80000000u; return true; }  // VNEG
            if(opc2 == 4 || opc2 == 5)                                                     // VCMP{E}
            {
                float a = sf(sd), b = opc2 == 5 ? 0.0f : sf(sm);
                uint32_t f = (a == b) ? 0x6 : (a < b) ? 0x8 : (a > b) ? 0x2 : 0x3;
                fpscr = (fpscr & 0x0FFFFFFFu) | (f << 28);
                return true;
            }
        }
    }
    return false;
}

//------------------------------------------------------------------------------
//  16-bit instructions
static void undefined(uint32_t op)
{
    fprintf(stderr, "cm4sim: undefined instruction %08x\n", op);
    die("undefined instruction");
}

static void exec16(uint32_t op)
{
    bool s = !in_it();
    int rd = op & 7, rn = (op >> 3) & 7, rm = (op >> 6) & 7;
    bool co, ov;

    switch(op >> 11)
    {
    case 0x00: case 0x01: case 0x02:   // LSL/LSR/ASR imm
    {
        int type = op >> 11, imm5 = (op >> 6) & 0x1F;
        uint32_t r = shift_imm(R[rn], type, imm5, &co);
        R[rd] = r; if(s) { setnz(r); C = co; }
        return;
    }
    case 0x03:
    {
        uint32_t b = (op & 0x400) ? (uint32_t)rm : R[rm];
        uint32_t r = (op & 0x200) ? add_c(R[rn], ~b, 1, &co, &ov) : add_c(R[rn], b, 0, &co, &ov);
        R[rd] = r; if(s) { setnz(r); C = co; V = ov; }
        return;
    }
    case 0x04: { int d = (op >> 8) & 7; R[d] = op & 0xFF; if(s) { setnz(R[d]); } return; }
    case 0x05: { int d = (op >> 8) & 7; uint32_t r = add_c(R[d], ~(op & 0xFF), 1, &co, &ov); setnz(r); C = co; V = ov; return; }
    case 0x06: { int d = (op >> 8) & 7; uint32_t r = add_c(R[d], op & 0xFF, 0, &co, &ov); R[d] = r; if(s) { setnz(r); C = co; V = ov; } return; }
    case 0x07: { int d = (op >> 8) & 7; uint32_t r = add_c(R[d], ~(op & 0xFF), 1, &co, &ov); R[d] = r; if(s) { setnz(r); C = co; V = ov; } return; }
    case 0x08:
        if((op & 0xFC00) == 0x4000)
        {
            int o = (op >> 6) & 0xF; uint32_t a = R[rd], b = R[rn], r = 0; bool wb = true;
            co = C; ov = V;
            switch(o)
            {
            case 0x0: r = a & b; break;
            case 0x1: r = a ^ b; break;
            case 0x2: r = shift_c(a, 0, b & 0xFF, C, &co); break;
            case 0x3: r = shift_c(a, 1, b & 0xFF, C, &co); break;
            case 0x4: r = shift_c(a, 2, b & 0xFF, C, &co); break;
            case 0x5: r = add_c(a, b, C, &co, &ov); break;
            case 0x6: r = add_c(a, ~b, C, &co, &ov); break;
            case 0x7: r = shift_c(a, 3, b & 0xFF, C, &co); break;
            case 0x8: r = a & b; wb = false; setnz(r); C = co; return;
            case 0x9: r = add_c(~b, 0, 1, &co, &ov); break;           // RSB #0
            case 0xA: r = add_c(a, ~b, 1, &co, &ov); setnz(r); C = co; V = ov; return;
            case 0xB: r = add_c(a, b, 0, &co, &ov); setnz(r); C = co; V = ov; return;
            case 0xC: r = a | b; break;
            case 0xD: r = a * b; break;
            case 0xE: r = a & ~b; break;
            case 0xF: r = ~b; break;
            }
            if(wb) R[rd] = r;
            if(s) { setnz(r); if(o != 0xD) { C = co; if(o == 5 || o == 6 || o == 9) V = ov; } }
            return;
        }
        if((op & 0xFC00) == 0x4400)
        {
            int d = (op & 7) | ((op >> 4) & 8), m = (op >> 3) & 0xF;
            switch((op >> 8) & 3)
            {
            case 0: { uint32_t r = rreg(d) + rreg(m); if(d == 15) branch_to(r | 1); else wreg(d, r); return; }
            case 1: { uint32_t r = add_c(rreg(d), ~rreg(m), 1, &co, &ov); setnz(r); C = co; V = ov; return; }
            case 2: if(d == 15) branch_to(rreg(m) | 1); else wreg(d, rreg(m)); return;
            case 3:
            {
                uint32_t t = rreg(m);
                if(op & 0x80) R[14] = (pc + 2) | 1;
                branch_to(t);
                return;
            }
            }
        }
        { int t = (op >> 8) & 7; R[t] = rd32((rreg(15) & ~3u) + (op & 0xFF) * 4); return; }   // LDR literal
    case 0x09:
        { int t = (op >> 8) & 7; R[t] = rd32((rreg(15) & ~3u) + (op & 0xFF) * 4); return; }
    case 0x0A: case 0x0B:
    {
        uint32_t a = R[rn] + R[rm];
        switch((op >> 9) & 7)
        {
        case 0: wr(a, R[rd], 4); return;
        case 1: wr(a, R[rd], 2); return;
        case 2: wr(a, R[rd], 1); return;
        case 3: R[rd] = ld(a, 1, true); return;
        case 4: R[rd] = ld(a, 4, false); return;
        case 5: R[rd] = ld(a, 2, false); return;
        case 6: R[rd] = ld(a, 1, false); return;
        case 7: R[rd] = ld(a, 2, true); return;
        }
        return;
    }
    case 0x0C: wr(R[rn] + ((op >> 6) & 0x1F) * 4, R[rd], 4); return;
    case 0x0D: R[rd] = ld(R[rn] + ((op >> 6) & 0x1F) * 4, 4, false); return;
    case 0x0E: wr(R[rn] + ((op >> 6) & 0x1F), R[rd], 1); return;
    case 0x0F: R[rd] = ld(R[rn] + ((op >> 6) & 0x1F), 1, false); return;
    case 0x10: wr(R[rn] + ((op >> 6) & 0x1F) * 2, R[rd], 2); return;
    case 0x11: R[rd] = ld(R[rn] + ((op >> 6) & 0x1F) * 2, 2, false); return;
    case 0x12: wr(rreg(13) + (op & 0xFF) * 4, R[(op >> 8) & 7], 4); return;
    case 0x13: R[(op >> 8) & 7] = rd32(rreg(13) + (op & 0xFF) * 4); return;
    case 0x14: R[(op >> 8) & 7] = (rreg(15) & ~3u) + (op & 0xFF) * 4; return;
    case 0x15: R[(op >> 8) & 7] = rreg(13) + (op & 0xFF) * 4; return;
    case 0x16: case 0x17:
        if((op & 0xFF00) == 0xB000) { uint32_t imm = (op & 0x7F) * 4; wreg(13, (op & 0x80) ? rreg(13) - imm : rreg(13) + imm); return; }
        if((op & 0xF500) == 0xB100)
        {
            uint32_t off = ((op >> 3) & 0x1F) * 2 + ((op >> 9) & 1) * 64;
            bool nz = op & 0x800;
            if((R[rd] != 0) == nz) next_pc = pc + 4 + off;
            return;
        }
        if((op & 0xFF00) == 0xB200)
        {
            uint32_t v = R[rn];
            switch((op >> 6) & 3)
            {
            case 0: R[rd] = (uint32_t)(int16_t)v; return;
            case 1: R[rd] = (uint32_t)(int8_t)v; return;
            case 2: R[rd] = v & 0xFFFF; return;
            case 3: R[rd] = v & 0xFF; return;
            }
        }
        if((op & 0xFE00) == 0xB400) { stm(13, (op & 0xFF) | ((op & 0x100) ? 0x4000 : 0), true, true); return; }
        if(op == 0xB662) { primask = 0; return; }
        if(op == 0xB672) { primask = 1; return; }
        if(op == 0xB661 || op == 0xB671) return;        // CPSIE/CPSID f: FAULTMASK not modelled
        if((op & 0xFF00) == 0xBA00)
        {
            uint32_t v = R[rn];
            switch((op >> 6) & 3)
            {
            case 0: R[rd] = __builtin_bswap32(v); return;
            case 1: R[rd] = ((v & 0x00FF00FFu) << 8) | ((v >> 8) & 0x00FF00FFu); return;
            case 3: R[rd] = (uint32_t)(int16_t)(((v & 0xFF) << 8) | ((v >> 8) & 0xFF)); return;
            }
        }
        if((op & 0xFE00) == 0xBC00) { ldm(13, (op & 0xFF) | ((op & 0x100) ? 0x8000 : 0), true, false); return; }
        if((op & 0xFF00) == 0xBE00) { fprintf(stderr, "cm4sim: BKPT #%u\n", op & 0xFF); die("breakpoint"); }
        if((op & 0xFF00) == 0xBF00)
        {
            if(op & 0xF) { itstate = op & 0xFF; return; }
            return;     // NOP, YIELD, WFE, WFI, SEV
        }
        undefined(op);
        return;
    case 0x18: stm(rd = (op >> 8) & 7, op & 0xFF, true, false); return;
    case 0x19: { int n = (op >> 8) & 7; ldm(n, op & 0xFF, !(op >> n & 1), false); return; }
    case 0x1A: case 0x1B:
    {
        int cond = (op >> 8) & 0xF;
        if(cond == 0xE) undefined(op);
        if(cond == 0xF) { fprintf(stderr, "cm4sim: SVC #%u\n", op & 0xFF); die("SVC not supported"); }
        if(cond_pass(cond)) next_pc = pc + 4 + ((int32_t)(int8_t)(op & 0xFF) << 1);
        return;
    }
    case 0x1C:
    {
        int32_t off = (int32_t)((op & 0x7FF) << 21) >> 20;
        next_pc = pc + 4 + off;
        return;
    }
    }
    undefined(op);
}

//------------------------------------------------------------------------------
//  32-bit instructions
static void exec32(uint32_t hw1, uint32_t hw2)
{
    uint32_t op = hw1 << 16 | hw2;
    bool co;

    // Load/store multiple, dual, exclusive, table branch
    if((hw1 & 0xFE00) == 0xE800)
    {
        int rn = hw1 & 0xF;
        if((hw1 & 0x0040) == 0)
        {
            int opc = (hw1 >> 7) & 3; bool W = hw1 & 0x20, L = hw1 & 0x10;
            if(opc == 1) { if(L) ldm(rn, hw2, W, false); else stm(rn, hw2, W, false); return; }
            if(opc == 2) { if(L) ldm(rn, hw2, W, true); else stm(rn, hw2, W, true); return; }
            undefined(op);
        }
        // dual / exclusive / table branch
        if((hw1 & 0xFFF0) == 0xE8D0 && (hw2 & 0xFFE0) == 0xF000)
        {
            int rm = hw2 & 0xF; bool h = hw2 & 0x10;
            uint32_t base = rreg(rn);
            uint32_t off = h ? rd(base + 2 * rreg(rm), 2) : rd(base + rreg(rm), 1);
            next_pc = pc + 4 + 2 * off;
            return;
        }
        if((hw1 & 0xFFF0) == 0xE850) { R[(hw2 >> 12) & 0xF] = rd32(rreg(rn) + (hw2 & 0xFF) * 4); return; }        // LDREX
        if((hw1 & 0xFFF0) == 0xE840) { wr32(rreg(rn) + (hw2 & 0xFF) * 4, rreg(hw2 >> 12)); R[(hw2 >> 8) & 0xF] = 0; return; }   // STREX
        if((hw1 & 0x0040) && ((hw1 & 0x0120) != 0))
        {
            bool P = hw1 & 0x100, U = hw1 & 0x80, W = hw1 & 0x20, L = hw1 & 0x10;
            int rt = hw2 >> 12, rt2 = (hw2 >> 8) & 0xF;
            uint32_t imm = (hw2 & 0xFF) * 4;
            uint32_t base = rn == 15 ? (rreg(15) & ~3u) : rreg(rn);
            uint32_t off = U ? base + imm : base - imm;
            uint32_t a = P ? off : base;
            if(L) { uint32_t v1 = rd32(a), v2 = rd32(a + 4); wreg(rt, v1); wreg(rt2, v2); }
            else  { wr32(a, rreg(rt)); wr32(a + 4, rreg(rt2)); }
            if(W) wreg(rn, off);
            return;
        }
        undefined(op);
    }

    // Data processing (shifted register)
    if((hw1 & 0xFE00) == 0xEA00)
    {
        int o = (hw1 >> 5) & 0xF, rn = hw1 & 0xF, rd = (hw2 >> 8) & 0xF, rm = hw2 & 0xF;
        bool s = hw1 & 0x10;
        int imm5 = ((hw2 >> 10) & 0x1C) | ((hw2 >> 6) & 3), type = (hw2 >> 4) & 3;
        uint32_t b = shift_imm(rreg(rm), type, imm5, &co);
        uint32_t a = (rn == 15 && (o == 2 || o == 3)) ? 0 : rreg(rn);
        if(rn == 15 && o == 2) { wreg(rd, b); if(s) { setnz(b); C = co; } return; }   // MOV/shift
        if(rn == 15 && o == 3) { wreg(rd, ~b); if(s) { setnz(~b); C = co; } return; }   // MVN
        if(o == 6) { undefined(op); }   // PKH
        if(!dp_op(o, rd, a, b, co, s)) undefined(op);
        return;
    }

    // Coprocessor (FP)
    if((hw1 & 0xEC00) == 0xEC00)
    {
        if(exec_coproc(hw1, hw2)) return;
        undefined(op);
    }

    // Branches and misc control
    if((hw1 & 0xF800) == 0xF000 && (hw2 & 0x8000))
    {
        int op1 = (hw2 >> 12) & 7;
        uint32_t Sb = (hw1 >> 10) & 1, J1 = (hw2 >> 13) & 1, J2 = (hw2 >> 11) & 1;
        if((op1 & 5) == 0)
        {
            int cond = (hw1 >> 6) & 0xF;
            if((cond & 0xE) != 0xE)
            {
                int32_t off = (int32_t)((Sb << 20) | (J2 << 19) | (J1 << 18) | ((hw1 & 0x3F) << 12) | ((hw2 & 0x7FF) << 1));
                off = off << 11 >> 11;
                if(cond_pass(cond)) next_pc = pc + 4 + off;
                return;
            }
            if((hw1 & 0xFFE0) == 0xF380) { msr(hw2 & 0xFF, rreg(hw1 & 0xF)); return; }
            if(hw1 == 0xF3AF) return;              // hints
            if(hw1 == 0xF3BF) return;              // DSB/DMB/ISB
            if(hw1 == 0xF3EF) { wreg((hw2 >> 8) & 0xF, mrs(hw2 & 0xFF)); return; }
            undefined(op);
        }
        uint32_t I1 = !(J1 ^ Sb), I2 = !(J2 ^ Sb);
        int32_t off = (int32_t)((Sb << 24) | (I1 << 23) | (I2 << 22) | ((hw1 & 0x3FF) << 12) | ((hw2 & 0x7FF) << 1));
        off = off << 7 >> 7;
        if(op1 & 4) R[14] = (pc + 4) | 1;
        if((op1 & 5) == 4) undefined(op);      // BLX imm
        next_pc = pc + 4 + off;
        return;
    }

    // Data processing (modified immediate)
    if((hw1 & 0xFA00) == 0xF000)
    {
        int o = (hw1 >> 5) & 0xF, rn = hw1 & 0xF, rd = (hw2 >> 8) & 0xF;
        bool s = hw1 & 0x10;
        uint32_t imm12 = ((hw1 & 0x400) << 1) | ((hw2 >> 4) & 0x700) | (hw2 & 0xFF);
        uint32_t b = expand_imm_c(imm12, &co);
        if(rn == 15 && o == 2) { wreg(rd, b); if(s) { setnz(b); C = co; } return; }
        if(rn == 15 && o == 3) { wreg(rd, ~b); if(s) { setnz(~b); C = co; } return; }
        if(!dp_op(o, rd, rreg(rn), b, co, s)) undefined(op);
        return;
    }

    // Data processing (plain binary immediate)
    if((hw1 & 0xFA00) == 0xF200)
    {
        int o = (hw1 >> 4) & 0x1F, rn = hw1 & 0xF, rd = (hw2 >> 8) & 0xF;
        uint32_t imm12 = ((hw1 & 0x400) << 1) | ((hw2 >> 4) & 0x700) | (hw2 & 0xFF);
        uint32_t imm16 = ((hw1 & 0xF) << 12) | imm12;
        int lsb = ((hw2 >> 10) & 0x1C) | ((hw2 >> 6) & 3), w = hw2 & 0x1F;
        uint32_t a = rn == 15 ? (rreg(15) & ~3u) : rreg(rn);
        switch(o)
        {
        case 0x00: wreg(rd, a + imm12); return;
        case 0x0A: wreg(rd, a - imm12); return;
        case 0x04: wreg(rd, imm16); return;
        case 0x0C: wreg(rd, (rreg(rd) & 0xFFFF) | (imm16 << 16)); return;
        case 0x14: { uint32_t v = rreg(rn) << (31 - (lsb + w)) ; wreg(rd, (uint32_t)((int32_t)v >> (31 - w))); return; } // SBFX
        case 0x1C: { uint32_t v = rreg(rn) >> lsb; wreg(rd, w == 31 ? v : v & ((2u << w) - 1)); return; } // UBFX
        case 0x16:
        {
            int msb = w;
            uint32_t mask = (msb >= 31 ? 0xFFFFFFFFu : ((2u << msb) - 1)) & ~((1u << lsb) - 1);
            uint32_t src = rn == 15 ? 0 : rreg(rn) << lsb;
            wreg(rd, (rreg(rd) & ~mask) | (src & mask));
            return;
        }
        }
        undefined(op);
    }

    // Load/store single
    if((hw1 & 0xFE00) == 0xF800)
    {
        bool sgn = hw1 & 0x100, L = hw1 & 0x10;
        int size = 1 << ((hw1 >> 5) & 3), rn = hw1 & 0xF, rt = hw2 >> 12;
        if(size == 8) undefined(op);
        uint32_t a; bool wb = false; uint32_t newb = 0;
        if(rn == 15)
        {
            if(!L) undefined(op);
            uint32_t base = rreg(15) & ~3u, imm = hw2 & 0xFFF;
            a = (hw1 & 0x80) ? base + imm : base - imm;
        }
        else if(hw1 & 0x80) a = rreg(rn) + (hw2 & 0xFFF);
        else if(hw2 & 0x800)
        {
            bool P = hw2 & 0x400, U = hw2 & 0x200, W = hw2 & 0x100;
            uint32_t imm = hw2 & 0xFF, base = rreg(rn);
            uint32_t off = U ? base + imm : base - imm;
            a = P ? off : base;
            if(W) { wb = true; newb = off; }
        }
        else if((hw2 & 0xFC0) == 0) a = rreg(rn) + (rreg(hw2 & 0xF) << ((hw2 >> 4) & 3));
        else { undefined(op); return; }

        if(L)
        {
            if(rt == 15 && size != 4) { if(wb) wreg(rn, newb); return; }     // PLD/PLI
            uint32_t v = ld(a, size, sgn);
            if(wb) wreg(rn, newb);
            if(rt == 15) load_pc(v); else wreg(rt, v);
        }
        else
        {
            wr(a, rreg(rt), size);
            if(wb) wreg(rn, newb);
        }
        return;
    }

    // Data processing (register)
    if((hw1 & 0xFF00) == 0xFA00 && (hw2 & 0xF000) == 0xF000)
    {
        int rn = hw1 & 0xF, rd = (hw2 >> 8) & 0xF, rm = hw2 & 0xF;
        int op1 = (hw1 >> 4) & 0xF, op2 = (hw2 >> 4) & 0xF;
        if(op2 == 0 && op1 < 8)
        {
            bool s = op1 & 1;
            uint32_t r = shift_c(rreg(rn), (op1 >> 1) & 3, rreg(rm) & 0xFF, C, &co);
            wreg(rd, r); if(s) { setnz(r); C = co; }
            return;
        }
        if(op1 < 8 && (op2 & 8))
        {
            int rot = ((hw2 >> 4) & 3) * 8;
            uint32_t v = rreg(rm); v = rot ? (v >> rot) | (v << (32 - rot)) : v;
            uint32_t add = rn == 15 ? 0 : rreg(rn);
            switch(op1)
            {
            case 0: wreg(rd, add + (uint32_t)(int16_t)v); return;
            case 1: wreg(rd, add + (v & 0xFFFF)); return;
            case 4: wreg(rd, add + (uint32_t)(int8_t)v); return;
            case 5: wreg(rd, add + (v & 0xFF)); return;
            }
        }
        if(op1 >= 8 && (op2 & 0xC) == 8)
        {
            uint32_t v = rreg(rm);
            int o = ((op1 & 3) << 2) | (op2 & 3);
            switch(o)
            {
            case 0x4: wreg(rd, __builtin_bswap32(v)); return;    // REV (op1=1001, op2=1000)
            case 0x5: wreg(rd, ((v & 0x00FF00FFu) << 8) | ((v >> 8) & 0x00FF00FFu)); return;
            case 0x6: { uint32_t r = 0; for(int i = 0; i < 32; i++) if(v >> i & 1) r |= 1u << (31 - i); wreg(rd, r); return; }
            case 0xC: wreg(rd, v ? __builtin_clz(v) : 32); return;
            }
        }
        undefined(op);
    }

    // Multiply
    if((hw1 & 0xFF80) == 0xFB00)
    {
        int rn = hw1 & 0xF, ra = hw2 >> 12, rd = (hw2 >> 8) & 0xF, rm = hw2 & 0xF;
        int op1 = (hw1 >> 4) & 7, op2 = (hw2 >> 4) & 3;
        if(op1 == 0 && op2 == 0) { wreg(rd, rreg(rn) * rreg(rm) + (ra == 15 ? 0 : rreg(ra))); return; }
        if(op1 == 0 && op2 == 1) { wreg(rd, rreg(ra) - rreg(rn) * rreg(rm)); return; }
        undefined(op);
    }
    if((hw1 & 0xFF80) == 0xFB80)
    {
        int rn = hw1 & 0xF, rlo = hw2 >> 12, rhi = (hw2 >> 8) & 0xF, rm = hw2 & 0xF;
        int op1 = (hw1 >> 4) & 7;
        switch(op1)
        {
        case 0: { int64_t r = (int64_t)(int32_t)rreg(rn) * (int32_t)rreg(rm); wreg(rlo, (uint32_t)r); wreg(rhi, (uint32_t)(r >> 32)); return; }
        case 2: { uint64_t r = (uint64_t)rreg(rn) * rreg(rm); wreg(rlo, (uint32_t)r); wreg(rhi, (uint32_t)(r >> 32)); return; }
        case 1: { int32_t a = rreg(rn), b = rreg(rm); wreg(rhi, b == 0 ? 0 : (b == -1 && a == INT32_MIN) ? (uint32_t)a : (uint32_t)(a / b)); return; }
        case 3: { uint32_t a = rreg(rn), b = rreg(rm); wreg(rhi, b ? a / b : 0); return; }
        case 6: { uint64_t acc = ((uint64_t)rreg(rhi) << 32) | rreg(rlo); acc += (uint64_t)rreg(rn) * rreg(rm); wreg(rlo, (uint32_t)acc); wreg(rhi, (uint32_t)(acc >> 32)); return; }
        case 4: { int64_t acc = (int64_t)(((uint64_t)rreg(rhi) << 32) | rreg(rlo)); acc += (int64_t)(int32_t)rreg(rn) * (int32_t)rreg(rm); wreg(rlo, (uint32_t)acc); wreg(rhi, (uint32_t)((uint64_t)acc >> 32)); return; }
        }
        undefined(op);
    }

    undefined(op);
}

//------------------------------------------------------------------------------
//  ELF loader
static uint32_t load_elf(const char *path)
{
    FILE *f = fopen(path, "rb");
    if(!f) { perror(path); exit(2); }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t *b = malloc(n);
    if(fread(b, 1, n, f) != (size_t)n) { perror("read"); exit(2); }
    fclose(f);
    if(memcmp(b, "\x7f" "ELF", 4) || b[4] != 1) { fprintf(stderr, "not ELF32\n"); exit(2); }
    uint32_t phoff, entry; uint16_t phnum, phentsize;
    memcpy(&entry, b + 24, 4); memcpy(&phoff, b + 28, 4);
    memcpy(&phentsize, b + 42, 2); memcpy(&phnum, b + 44, 2);
    for(int i = 0; i < phnum; i++)
    {
        uint8_t *ph = b + phoff + i * phentsize;
        uint32_t type, off, vaddr, paddr, filesz, memsz;
        memcpy(&type, ph, 4); memcpy(&off, ph + 4, 4); memcpy(&vaddr, ph + 8, 4);
        memcpy(&paddr, ph + 12, 4); memcpy(&filesz, ph + 16, 4); memcpy(&memsz, ph + 20, 4);
        if(type != 1) continue;
        // load at physical (load) address; startup code copies .data
        uint8_t *dst = mem_ptr(paddr, memsz ? memsz : 1);
        if(!dst) { fprintf(stderr, "segment at %08x outside memory\n", paddr); exit(2); }
        memcpy(dst, b + off, filesz);
    }
    free(b);
    return entry;
}

//------------------------------------------------------------------------------
int main(int argc, char **argv)
{
    const char *img = NULL;
    uint64_t seed = 1;
    for(int i = 1; i < argc; i++)
    {
        if(!strcmp(argv[i], "-s") && i + 1 < argc) seed = strtoull(argv[++i], 0, 0);
        else if(!strcmp(argv[i], "-r") && i + 1 < argc) dev_rate = strtoul(argv[++i], 0, 0);
        else if(!strcmp(argv[i], "-m") && i + 1 < argc) max_cycles = strtoull(argv[++i], 0, 0);
        else if(!strcmp(argv[i], "-t")) trace = true;
        else if(!strcmp(argv[i], "-f")) fpu_present = true;
        else if(!strcmp(argv[i], "-x")) strict_ret = true;
        else img = argv[i];
    }
    if(!img) { fprintf(stderr, "usage: cm4sim [-s seed] [-r rate] [-m max_cycles] [-t] [-f] image.elf\n"); return 2; }
    rng_state = seed * 0x9E3779B97F4A7C15ull + 1;
    dev_scratch[0] = (uint32_t)seed;

    load_elf(img);
    msp = rd32(0) & ~3u;
    pc = rd32(4) & ~1u;

    for(;;)
    {
        if(cyc >= max_cycles) die("cycle limit");

        // SysTick
        if(st_ctrl & 1)
        {
            if(st_val == 0) st_val = st_load;
            else if(--st_val == 0)
            {
                st_ctrl |= 0x10000u;
                if(st_ctrl & 2) set_pending(EXC_SYSTICK);
            }
        }
        // random asynchronous interrupts
        if(dev_rand_mask && dev_rate && rnd32() % 1000000u < dev_rate)
        {
            int n;
            do n = rnd32() & 31; while(!(dev_rand_mask >> n & 1));
            if(!pending[16 + n] && !active[16 + n]) set_pending(16 + n);   // keeps latency measurement exact
        }

        check_exceptions();

        uint32_t hw1 = rd(pc, 2);
        bool is32 = (hw1 >> 11) >= 0x1D;
        uint32_t hw2 = is32 ? rd(pc + 2, 2) : 0;
        next_pc = pc + (is32 ? 4 : 2);
        if(trace) fprintf(stderr, "%08x: %04x%s%04x  sp=%08x bp=%02x pm=%u\n", pc, hw1, is32 ? " " : "", is32 ? hw2 : 0, *cur_sp(), basepri, primask);

        exc_returned = false;
        bool it = in_it();
        bool is_it_instr = !is32 && (hw1 & 0xFF00) == 0xBF00 && (hw1 & 0xF);
        if(it && !cond_pass(itstate >> 4))
        {
            // skipped
        }
        else if(is32) exec32(hw1, hw2);
        else exec16(hw1);

        if(it && !is_it_instr && !exc_returned)
            itstate = (itstate & 7) == 0 ? 0 : (itstate & 0xE0) | ((itstate << 1) & 0x1F);

        pc = next_pc;
        cyc++;
    }
}
